local LongbowMaker = {}
local PRODUCTS = {
    simple_yew_longbow = { name = "Preprost tisolni lok", woodCost = 3, ropeCost = 1, time = 4, cost = 80, attack = 28, happiness = 1, description = "Preprost tisolni lok za lokostrelce." },
    laminated_horn_longbow = { name = "Laminirani rogovi lok", woodCost = 3, leatherCost = 1, ropeCost = 1, time = 7, cost = 220, attack = 42, happiness = 2, prestige = 2, description = "Laminirani rogovi lok za trgovce." },
    silver_tipped_longbow = { name = "Srebrnokončni lok", woodCost = 3, silverCost = 1, leatherCost = 1, ropeCost = 1, time = 10, cost = 540, attack = 56, happiness = 2, prestige = 6, description = "Srebrnokončni lok za plemiče." },
    gold_inlaid_longbow = { name = "Zlatovloženi lok", woodCost = 3, goldCost = 1, silverCost = 1, leatherCost = 1, ropeCost = 1, time = 14, cost = 1300, attack = 70, happiness = 3, prestige = 14, description = "Zlatovloženi lok za visoke plemiče." },
    jewel_grip_longbow = { name = "Draguljnoročajni lok", woodCost = 3, goldCost = 1, silverCost = 1, leatherCost = 1, ropeCost = 1, jewelCost = 1, time = 18, cost = 2900, attack = 82, happiness = 5, prestige = 27, description = "Lok z draguljnim ročajem za visoko plemstvo." },
    royal_grand_longbow = { name = "Kraljevski veliki lok", woodCost = 5, goldCost = 2, silverCost = 2, leatherCost = 1, ropeCost = 1, jewelCost = 2, pearlCost = 2, time = 25, cost = 6500, attack = 95, happiness = 12, prestige = 58, description = "Veliki kraljevski lok z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    longbow_workshop = { name = "Lokarska delavnica", cost = { gold = 260, wood = 160, stone = 100, rope = 6 }, upkeep = 6, qualityBonus = 5 },
    bowyer_loft = { name = "Lokarska podstrešje", cost = { gold = 950, wood = 320, stone = 240, silver = 6, leather = 6 }, upkeep = 22, qualityBonus = 18 },
    master_bowyer_atelier = { name = "Mojstrski lokarski atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_longbow_palace = { name = "Kraljevska lokarska palača", cost = { gold = 11500, wood = 600, stone = 800, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
LongbowMaker.woodStock = 18; LongbowMaker.ropeStock = 12; LongbowMaker.leatherStock = 10; LongbowMaker.silverStock = 6; LongbowMaker.goldStock = 6; LongbowMaker.jewelStock = 4; LongbowMaker.pearlStock = 4
LongbowMaker.productStock = {}; LongbowMaker.buildings = {}; LongbowMaker.maker = nil; LongbowMaker.activeMaking = {}; LongbowMaker.totalProducts = 0; LongbowMaker.dayTimer = 0
function LongbowMaker.init() LongbowMaker.woodStock=18; LongbowMaker.ropeStock=12; LongbowMaker.leatherStock=10; LongbowMaker.silverStock=6; LongbowMaker.goldStock=6; LongbowMaker.jewelStock=4; LongbowMaker.pearlStock=4; LongbowMaker.productStock={}; LongbowMaker.buildings={}; LongbowMaker.maker=nil; LongbowMaker.activeMaking={}; LongbowMaker.totalProducts=0; LongbowMaker.dayTimer=0; print("[LongbowMaker] Royal Longbow Maker System initialized (6 products, 4 buildings)") end
function LongbowMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LongbowMaker.maker={name=n or ("Lokar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lokar najet: %s (spretnost: %d)",LongbowMaker.maker.name,s),"success") end; return true end
function LongbowMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LongbowMaker.build(id) local ok,e=LongbowMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LongbowMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LongbowMaker.getQualityBonus() local b=0; for _,bd in ipairs(LongbowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LongbowMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and LongbowMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ropeCost and LongbowMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.leatherCost and LongbowMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and LongbowMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LongbowMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and LongbowMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LongbowMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LongbowMaker.buildings==0 then return false,"Potrebna lokarska delavnica" end; if not LongbowMaker.maker then return false,"Potreben lokar" end; return true end
function LongbowMaker.make(pt,qty) qty=qty or 1; local ok,e=LongbowMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then LongbowMaker.woodStock=LongbowMaker.woodStock-d.woodCost*qty end; if d.ropeCost then LongbowMaker.ropeStock=LongbowMaker.ropeStock-d.ropeCost*qty end; if d.leatherCost then LongbowMaker.leatherStock=LongbowMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then LongbowMaker.silverStock=LongbowMaker.silverStock-d.silverCost*qty end; if d.goldCost then LongbowMaker.goldStock=LongbowMaker.goldStock-d.goldCost*qty end; if d.jewelCost then LongbowMaker.jewelStock=LongbowMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LongbowMaker.pearlStock=LongbowMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LongbowMaker.maker then t=math.max(1,t-math.floor(LongbowMaker.maker.skill/12)) end; table.insert(LongbowMaker.activeMaking,{id="longbow_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LongbowMaker.completeMaking(m) local q=1.0+(LongbowMaker.getQualityBonus()/100); if LongbowMaker.maker then q=q+(LongbowMaker.maker.skill/140) end; q=math.min(2.5,q); LongbowMaker.productStock[m.productType]=(LongbowMaker.productStock[m.productType] or 0)+m.quantity; LongbowMaker.totalProducts=LongbowMaker.totalProducts+m.quantity; if m.attack>0 and _G.state then _G.state.attack=(_G.state.attack or 0)+m.attack end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LongbowMaker.maker then LongbowMaker.maker.itemsMade=LongbowMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LongbowMaker.maker.skill=math.min(100,LongbowMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Lok izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"longbow.completed",{productName=m.productName,attack=m.attack,prestige=m.prestige,happiness=m.happiness}) end end
function LongbowMaker.update(dt) if not _G.state then return end; LongbowMaker.dayTimer=LongbowMaker.dayTimer+dt; if LongbowMaker.dayTimer>=30 then LongbowMaker.dayTimer=0; for i=#LongbowMaker.activeMaking,1,-1 do local m=LongbowMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LongbowMaker.completeMaking(m); table.remove(LongbowMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LongbowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LongbowMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LongbowMaker.getStats() return {woodStock=LongbowMaker.woodStock,ropeStock=LongbowMaker.ropeStock,leatherStock=LongbowMaker.leatherStock,silverStock=LongbowMaker.silverStock,goldStock=LongbowMaker.goldStock,jewelStock=LongbowMaker.jewelStock,pearlStock=LongbowMaker.pearlStock,productStock=LongbowMaker.productStock,numBuildings=#LongbowMaker.buildings,hasMaker=LongbowMaker.maker~=nil,makerName=LongbowMaker.maker and LongbowMaker.maker.name or "—",makerSkill=LongbowMaker.maker and LongbowMaker.maker.skill or 0,activeMaking=#LongbowMaker.activeMaking,totalProducts=LongbowMaker.totalProducts} end
return LongbowMaker
